@Override
    public void endElement(String uri, String localName, String qName) throws SAXException {
        String name = localName(localName, qName);

        if (name.equals("script") || name.equals("style")) {
            suppressDepth = Math.max(0, suppressDepth - 1);
            return;
        }
        if (suppressDepth > 0) {
            return;
        }

        switch (name) {
            case "h1":
            case "h2":
            case "h3":
            case "h4":
            case "h5":
            case "h6":
            case "p":
            case "blockquote":
            case "ul":
            case "ol":
            case "li":
            case "b":
            case "strong":
            case "i":
            case "em":
            case "s":
            case "strike":
            case "del":
            case "a":
                closeImplicitParagraph();
                pop();
                break;
            case "dt":
                pop(); // StrongEmphasis
                pop(); // Paragraph
                break;
            case "dd":
                pop();
                break;
            case "pre":
                if (codeBlock != null) {
                    codeBlock.setLiteral(withTrailingNewline(codeBlockText.toString()));
                    codeBlock = null;
                    codeBlockText = null;
                }
                break;
            case "code":
                if (inlineCode != null) {
                    inlineCode.setLiteral(inlineCodeText.toString());
                    inlineCode = null;
                    inlineCodeText = null;
                }
                break;
            case "div":
                closeImplicitParagraph();
                break;
            case "table":
                endTable();
                break;
            case "tr":
                if (tableDepth == 1) {
                    pop();
                    rowIndex++;
                }
                break;
            case "th":
            case "td":
                if (tableDepth == 1) {
                    pop();
                }
                break;
            default:
                break;
        }
    }

